using GPC.Checkers.Geotechnics.Walls;

namespace GeotechnicsTests
{
    /// <summary>
    /// Frozen reference: the fixed cases of the version 1 wall documents as ANTHEA wrote them until 1.15.0 (RetainingWall.LegacyCombinations,
    /// X.Calculations/RetainingWall.Library.cs of ANTHEA f52f5a76, with RetainingWall.DefaultPassiveFactor), copied when they became
    /// <see cref="WallCombinations.Version1"/>, generated by Model (census of the combinations, D7 a). The document values arrive as parameters.
    /// <see cref="WallCombinationsEquivalenceTests"/> compares the two bit for bit. Do not edit: it is the behaviour before the migration.
    /// </summary>
    internal static class FrozenWallVersion1Combinations
    {
        public static IReadOnlyList<WallCombination> Generate(bool water, bool heel, double psi1, double psi2, double? seismicKh, double seismicKv)
        {
            var result = new List<WallCombination>();
            void Add(string name, WallLimitState state, double fc, double fs, double fq, double fw = 1, double kh = 0, double kv = 0)
            {
                bool design = state is WallLimitState.Ultimate or WallLimitState.Seismic;
                foreach (bool onHeel in design && heel && fq > 0 ? new[] { true, false } : new[] { true })
                    result.Add(new WallCombination(onHeel ? name : name + "b", state, fc, fs, fs, fw, 1, design ? 1.1 : 1, design ? 1.15 : 1, state == WallLimitState.Seismic ? 1.2 : design ? 1.4 : 1, kh, kv,
                        new Dictionary<string, double> { ["q"] = fq, ["hq"] = fq, ["nq"] = fq }, variableSurchargeOnHeel: onHeel, passiveFactor: state == WallLimitState.Ultimate ? 1.4 : 1));
            }
            Add("Caratteristica", WallLimitState.Characteristic, 1, 1, 1); Add("Frequente", WallLimitState.Frequent, 1, 1, psi1); Add("Quasi permanente", WallLimitState.QuasiPermanent, 1, 1, psi2);
            int index = 0;
            foreach (double fc in new[] { 1d, 1.3 }) foreach (double fs in new[] { 1d, 1.3 }) foreach (double fq in new[] { 0d, 1.5 }) foreach (double fw in water ? new[] { 1d, 1.3 } : new[] { 1d })
                Add("SLU " + ++index, WallLimitState.Ultimate, fc, fs, fq, fw);
            if (seismicKh != null) foreach (double kv in new[] { -seismicKv, seismicKv }.Distinct())
                Add(kv < 0 ? "Sisma kv−" : "Sisma kv+", WallLimitState.Seismic, 1, 1, psi2, 1, seismicKh.Value, kv);
            return result;
        }
    }
}
